public class RadixTranscoderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object call(String number, int from, int to) {
        try {
            return RadixTranscoder.convert(number, from, to);
        } catch (IllegalArgumentException e) {
            return "IAE";
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("convert(\"255\", 10, 16)", "FF", call("255", 10, 16));
        check("convert(\"ff\", 16, 2)", "11111111", call("ff", 16, 2));
        check("convert(\"-1010\", 2, 10)", "-10", call("-1010", 2, 10));
        check("convert(\"00042\", 10, 10)", "42", call("00042", 10, 10));
        check("convert(\"zz\", 36, 10)", "1295", call("zz", 36, 10));
        check("convert(\"-0\", 10, 7) is plain zero", "0", call("-0", 10, 7));
        check("convert(\"1234567\", 8, 36)", "7C6V", call("1234567", 8, 36));
        check("bad digit for base 2", "IAE", call("12", 2, 10));
        check("radix 1 rejected", "IAE", call("5", 1, 10));
        check("lone minus rejected", "IAE", call("-", 10, 2));
        check("null rejected", "IAE", call(null, 10, 2));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

