public class RadixTranscoder {

    private static final String DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

    public static String convert(String number, int fromRadix, int toRadix) {
        if (fromRadix < 2 || fromRadix > 36 || toRadix < 2 || toRadix > 36) {
            throw new IllegalArgumentException("radix out of range");
        }
        if (number == null || number.isEmpty()) {
            throw new IllegalArgumentException("empty numeral");
        }
        boolean negative = number.charAt(0) == '-';
        int start = negative ? 1 : 0;
        if (start >= number.length()) {
            throw new IllegalArgumentException("no digits");
        }
        long value = 0;
        for (int i = start; i < number.length(); i++) {
            int digit = digitValue(number.charAt(i));
            if (digit < 0 || digit >= fromRadix) {
                throw new IllegalArgumentException("bad digit: " + number.charAt(i));
            }
            value = value * fromRadix + digit;
        }
        if (value == 0) {
            return "0";
        }
        StringBuilder sb = new StringBuilder();
        while (value > 0) {
            sb.append(DIGITS.charAt((int) (value % toRadix)));
            value /= toRadix;
        }
        if (negative) {
            sb.append('-');
        }
        return sb.reverse().toString();
    }

    private static int digitValue(char c) {
        if (c >= '0' && c <= '9') {
            return c - '0';
        }
        if (c >= 'a' && c <= 'z') {
            return c - 'a' + 10;
        }
        if (c >= 'A' && c <= 'Z') {
            return c - 'A' + 10;
        }
        return -1;
    }
}
